"""Actual Python debugger and Node output-channel UI, with an isolated profile."""
import argparse,io,json,sys,tempfile,threading,zipfile
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from backend.server import Application,LumenServer
from playwright.sync_api import sync_playwright,expect

def main():
 parser=argparse.ArgumentParser();parser.add_argument('--output',type=Path,required=True);out=parser.parse_args().output;out.mkdir(parents=True,exist_ok=True);checks=[];errors=[]
 def passed(name):checks.append(name);print('PASS',name,flush=True)
 with tempfile.TemporaryDirectory(prefix='zenit-r8-') as tmp:
  base=Path(tmp);ws=base/'project';ws.mkdir();(ws/'main.py').write_text('value=2\nanswer=value+40\nprint(answer)\n');(ws/'other.py').write_text('other=1\nother+=1\nprint(other)\n')
  app=Application(ROOT,ws,data_dir=base/'profile');app.workspace.trusted=True;app.features.studio.update({'onboarded':True});app.features.prefs.update({'general.showWelcome':False,'appearance.motion':False,'updates.automatic':False})
  code="""const v=require('vscode');exports.activate=()=>{const a=v.window.createOutputChannel('QA · texto'),b=v.window.createOutputChannel('QA · registro',{log:true});let changes=[];b.onDidChangeLogLevel(level=>changes.push(level));v.commands.registerCommand('qa.hidden',()=>{a.appendLine('Canal oculto · ñ');return true;});v.commands.registerCommand('qa.log',()=>{b.debug('debug real');b.info('info real');b.show(true);return true;});v.commands.registerCommand('qa.level',()=>({level:b.logLevel,changes}));};"""
  raw=io.BytesIO()
  with zipfile.ZipFile(raw,'w') as archive:archive.writestr('extension/package.json',json.dumps({'publisher':'qa','name':'output','version':'1','main':'main.cjs'}));archive.writestr('extension/main.cjs',code)
  store=app.features.extensions;review=store.inspect_bytes(raw.getvalue());store.install(review['ticket'],True);runtime=app.features.extension_runtime;runtime.start(app.workspace,'qa.output',True)
  server=LumenServer(0,app);threading.Thread(target=server.serve_forever,daemon=True).start()
  try:
   with sync_playwright() as pw:
    browser=pw.chromium.launch(channel='msedge',headless=True);page=browser.new_page(viewport={'width':1672,'height':917});page.on('pageerror',lambda error:errors.append(str(error)))
    def inject(route):
     response=route.fetch();route.fulfill(response=response,body=response.text()+'\nwindow.__qa={get studio(){return studio},get editor(){return editor},get platform(){return platformUI},openFile};')
    page.route('**/src/app.js',inject);page.goto(f'http://127.0.0.1:{server.server_port}');page.wait_for_function('window.lumen?.ready');page.evaluate('async()=>{await __qa.openFile("main.py");__qa.editor.breakpoints.set("main.py",new Set([2]));__qa.editor.breakpoints.set("other.py",new Set([3]));await __qa.studio.debug();}')
    expect(page.locator('[data-debug-pane]:visible')).to_have_count(1);expect(page.locator('#debug-input-form')).to_be_hidden();expect(page.locator('#debug-breakpoints')).to_have_value('2');page.locator('#debug-file').select_option('other.py');expect(page.locator('#debug-breakpoints')).to_have_value('3');page.locator('#debug-file').select_option('main.py');expect(page.locator('#debug-file-trigger')).to_be_visible();passed('One inspector and its file selector are visible; each file loads its own breakpoints')
    page.wait_for_function('!__qa.studio.debugWorkspace.polling&&!__qa.studio.debugWorkspace.pending&&document.querySelector("#debug-file-trigger")?.textContent==="main.py"')
    idle=page.evaluate('async()=>{let count=0;const observer=new MutationObserver(events=>count+=events.length);observer.observe(document.querySelector(".debug-page"),{subtree:true,attributes:true,childList:true,characterData:true});await new Promise(r=>setTimeout(r,800));observer.disconnect();return count;}');assert idle==0,idle;page.screenshot(path=str(out/'debug-idle.png'));passed('Idle debugging causes zero DOM mutations');page.evaluate('async()=>{window.__debugRoot=document.querySelector(".debug-page");__qa.platform.closePage();await __qa.studio.debug();}');assert page.evaluate('__debugRoot===document.querySelector(".debug-page")');passed('Closing and reopening Debug retains the actual page nodes')
    page.locator('#debug-start').click();expect(page.locator('#debug-state')).to_have_text('En pausa',timeout=20000);page.locator('[data-debug=next]').click();expect(page.locator('#debug-variables')).to_contain_text('value',timeout=20000);page.evaluate('window.__variablesNode=document.querySelector("#debug-variables");window.__breakpointsNode=document.querySelector("#debug-breakpoints")');page.locator('[data-debug=next]').click();expect(page.locator('#debug-variables')).to_contain_text('42',timeout=20000);passed('Real Python next-step computes and displays answer = 42')
    page.locator('[data-debug-tab=stack]').click();expect(page.locator('.stack-frame')).to_have_count(1);page.locator('[data-debug-tab=variables]').click();assert page.evaluate('__variablesNode===document.querySelector("#debug-variables")&&__breakpointsNode===document.querySelector("#debug-breakpoints")');
    page.wait_for_function('!__qa.studio.debugWorkspace.pending&&!__qa.studio.debugWorkspace.polling')
    paused=page.evaluate('async()=>{let count=0;const observer=new MutationObserver(events=>count+=events.length);observer.observe(document.querySelector(".debug-page"),{subtree:true,attributes:true,childList:true,characterData:true});await new Promise(r=>setTimeout(r,900));observer.disconnect();return count;}');assert paused==0,paused;page.screenshot(path=str(out/'debug-paused.png'));passed('Inspector switching preserves nodes and unchanged paused polling has zero mutations')
    page.locator('[data-debug=continue]').click();expect(page.locator('#debug-state')).to_have_text('Ejecución finalizada',timeout=20000);page.locator('[data-debug-tab=output]').click();expect(page.locator('#debug-output')).to_contain_text('42');page.locator('#debug-clear').click();expect(page.locator('#debug-output')).to_have_text('');await_output=app.features.debugger.snapshot()['output'];assert '42' in await_output;passed('Clearing the displayed output keeps the real debugger transcript')
    page.locator('.debug-setup summary').click();page.locator('#debug-breakpoints').fill('1, invalid');page.locator('#debug-start').click();expect(page.locator('.debug-feedback')).to_contain_text('números de línea');passed('Invalid breakpoints produce an inline error without losing the session view')
    for width,height in [(1280,720),(1366,768),(1920,1080)]:
     page.set_viewport_size({'width':width,'height':height});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path=str(out/f'debug-{width}.png'))
    passed('Debugging fits 1280x720, 1366x768 and 1920x1080')
    page.evaluate('__qa.platform.closePage()');runtime.request(app.workspace,{'id':'qa.output','method':'command','command':'qa.hidden'});page.locator('[data-terminal=output]').click();expect(page.locator('[data-output-channel]')).to_contain_text('QA · texto');expect(page.locator('#terminal-content')).to_contain_text('Canal oculto · ñ');passed('A real hidden extension output channel can be selected and read')
    page.locator('[data-output-channel]').click();page.locator('.menu-item').filter(has_text='QA · registro').click();expect(page.locator('[data-output-level]')).to_contain_text('Info');page.locator('[data-output-level]').click();page.locator('.menu-item').filter(has_text='Debug').click();expect(page.locator('[data-output-level]')).to_contain_text('Debug');state=runtime.request(app.workspace,{'id':'qa.output','method':'command','command':'qa.level'})['result'];assert state=={'level':2,'changes':[2]},state;runtime.request(app.workspace,{'id':'qa.output','method':'command','command':'qa.log'});expect(page.locator('#terminal-content')).to_contain_text('debug real');passed('The UI changes real LogOutputChannel.logLevel and fires its extension event')
    page.screenshot(path=str(out/'extension-output.png'));page.locator('[data-output-clear]').click();expect(page.locator('#terminal-content')).to_have_text('');page.locator('[data-output-level]').click();page.locator('.menu-item').filter(has_text='Desactivado').click();expect(page.locator('[data-output-level]')).to_contain_text('Desactivado');runtime.request(app.workspace,{'id':'qa.output','method':'command','command':'qa.log'});page.wait_for_timeout(600);expect(page.locator('#terminal-content')).to_have_text('');passed('Clear dispatches to the channel and Off suppresses log writes')
    assert not errors,errors;passed('No uncaught JavaScript errors');browser.close()
  finally:server.shutdown();server.server_close();app.features.shutdown();app.runner.shutdown()
 (out/'verification.json').write_text(json.dumps({'checks':checks,'errors':errors,'idleMutations':idle,'pausedMutations':paused,'realPython':True,'realNodeExtension':True},indent=2),encoding='utf-8')
if __name__=='__main__':main()
